'use strict';
// A PRIVATE staged site, never production. The real DOM, store and service worker
// are used; seeds are synthetic histories generated by the real engine.
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),http=require('node:http');
const {chromium,webkit}=require('playwright');
const root=path.resolve(process.argv[2]||'_reprise6_d_private'),engine=process.env.PW_BROWSER||'chromium';
assert(['chromium','webkit'].includes(engine));
assert(fs.readFileSync(path.join(root,'quizz.html'),'utf8').includes('coherenceAtomic:window.QPJBReprise6D'));
const mime={'.html':'text/html; charset=utf-8','.js':'application/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.json':'application/json','.png':'image/png','.svg':'image/svg+xml','.webp':'image/webp'};
let offline=false,refused=0;
const server=http.createServer((req,res)=>{
 if(offline){refused++;res.writeHead(503);return res.end('offline')}
 try{
  const u=new URL(req.url,'http://localhost');if(!u.pathname.startsWith('/QPJB/'))throw Error('path');
  let file=path.resolve(root,decodeURIComponent(u.pathname.slice(6)));
  if(file!==root&&!file.startsWith(root+path.sep))throw Error('path');
  if(fs.statSync(file).isDirectory())file=path.join(file,'index.html');
  if(!fs.statSync(file).isFile())throw Error('file');
  res.writeHead(200,{'content-type':mime[path.extname(file)]||'application/octet-stream'});
  fs.createReadStream(file).on('error',()=>res.destroy()).pipe(res);
 }catch(e){res.writeHead(404);res.end('Not found')}
});
async function main(){
 await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
 const origin='http://127.0.0.1:'+server.address().port,home=origin+'/QPJB/',url=home+'quizz.html';
 const browser=await ({chromium,webkit})[engine].launch({headless:true,args:engine==='chromium'?['--no-sandbox']:[]});
 const rows=[];
 try{
 for(const width of [360,1280]){
  offline=false;const context=await browser.newContext({viewport:{width,height:800},serviceWorkers:'allow',reducedMotion:'reduce'});
  try{
   const page=await context.newPage(),errors=[];
   page.on('pageerror',e=>errors.push(e.message));
   const snapshot=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('qpjb-sef-parcours-01')));
   const write=s=>page.evaluate(s=>localStorage.setItem('qpjb-sef-parcours-01',JSON.stringify(s)),s);
   const reload=async()=>{await page.reload({waitUntil:'domcontentloaded'});await page.locator('#parcours-start').waitFor({state:'visible'})};
   const step=async(i,n)=>page.waitForFunction(([i,n])=>document.querySelector('#step')?.textContent.includes(i+' / '+n),[i,n]);
   const start=async(selector='#parcours-start')=>{await page.locator(selector).click();await page.locator('#question-heading').waitFor({state:'visible'})};
   const skip=async()=>page.locator('#pass').click();
   await page.goto(home,{waitUntil:'domcontentloaded'});
   await page.evaluate(async()=>{await navigator.serviceWorker.register('/QPJB/service-worker.js');await navigator.serviceWorker.ready});
   await page.waitForFunction(()=>!!navigator.serviceWorker.controller,null,{timeout:35000});
   const warm=await page.evaluate(()=>new Promise(resolve=>{const c=new MessageChannel();c.port1.onmessage=e=>resolve(e.data);navigator.serviceWorker.controller.postMessage({type:'QPJB_PREFETCH_OFFLINE'},[c.port2])}));
   assert.deepEqual(warm,{type:'QPJB_OFFLINE_READY',ok:true});
   const cached=await page.evaluate(async()=>{const keys=(await Promise.all((await caches.keys()).map(async k=>(await (await caches.open(k)).keys()).map(r=>r.url)))).flat();return ['/QPJB/quizz-parcours.js?v=22','/QPJB/quizz-prerequis.js?v=3'].every(x=>keys.some(k=>new URL(k).pathname+new URL(k).search===x))});
   assert(cached,'T engine and metadata cache keys');
   // First-ever Quiz visit is offline, not just a warmed tab.
   offline=true;await context.setOffline(true);
   await page.goto(url,{waitUntil:'domcontentloaded'});await page.locator('#parcours-start').waitFor({state:'visible'});
   const fixture=await page.evaluate(()=>{
    const api=QPJBParcours,all=JSON.parse(document.querySelector('#training-data').textContent).exercises;
    if(all.length!==1915||QPJBReprise6D.mode!=='T'||QPJBDurableIntegration.schema!=='QPJB_DURABLE_INTEGRATION_V1')throw Error('missing real modules');
    const m3=QPJB_COHERENCE_M3,base={coherenceM2:QPJBCoherenceM2,coherenceFullOrder:true,transitionGroups:[{simple:m3.TEXAS_ELEMENTARY,complex:m3.TEXAS},{simple:m3.STAYMAN_SIMPLE,complex:m3.STAYMAN_FOURTH}]};
    const copy=x=>JSON.parse(JSON.stringify(x)),state=api.empty(),events=[];
    for(let s=1;s<=2;s++){
     const deck=api.start(state,all,base);for(const [i,q] of deck.entries())if(!api.record(state,q,'correct',i,q.answer,false,false))throw Error('record seed');
     if(!api.finish(state,all))throw Error('finish seed');
    }
    const before=copy(state),a=copy(state),b=copy(state);
    const reference=api.start(a,all,base).map(q=>q.id),expected=api.start(b,all,{...base,coherenceAtomic:QPJBReprise6D,observe:e=>events.push(e)}).map(q=>q.id);
    const old=all.find(q=>q.id==='SEF-005-2'),next=all.find(q=>q.id==='SEF-005-1');
    api.record(a,all.find(q=>q.id===reference[0]),'skipped',0,null,false,false);api.move(a,1);
    return {before,reference,expected,events,legacy:a,old,next};
   });
   assert(fixture.reference.includes('SEF-005-2')&&fixture.expected.includes('SEF-005-1'));
   assert(!fixture.expected.includes('SEF-005-2'));assert.equal(fixture.events.filter(e=>e.atomicChoice).length,1);
   assert.deepEqual(fixture.reference.filter(id=>id!=='SEF-005-2').sort(),fixture.expected.filter(id=>id!=='SEF-005-1').sort());
   await write(fixture.before);await reload();await start();
   let state=await snapshot();assert.deepEqual(state.active.ids,fixture.expected,'T must change real UI deck');
   const target=fixture.expected.indexOf('SEF-005-1'),displayed=[];
   for(let i=0;i<10;i++){
    await step(i+1,10);
    assert.equal(await page.locator('[data-early-contrast]').count(),0,'no contrast before session completion');
    if(i===target){
     assert.deepEqual(await page.locator('.hand .rank').allTextContents(),fixture.next.hand.map(s=>s.join('')),'actually rendered hand');
     assert((await page.locator('#body .meta').textContent()).includes(fixture.next.h+' points H'));
    }
    displayed.push((await snapshot()).active.ids[i]);
    await skip();
    if(i===0){
     await step(2,10);const active=(await snapshot()).active;
     await reload();await start();await step(2,10);
     assert.deepEqual((await snapshot()).active,active,'exact active resume offline');
    }
   }
   await page.locator('#done-home').waitFor({state:'visible'});
   state=await snapshot();assert.equal(state.completed,3);assert.equal(state.active,null);
   assert.deepEqual(state.journal.at(-1).answers.map(a=>a.id),displayed);
   assert.deepEqual(displayed,fixture.expected);
   const panel=page.locator('[data-early-contrast="SEF-PN26-M1-021"]');assert(await panel.isVisible(),'actual completed S3 missing-fit contrast');assert.match(await panel.innerText(),/hors score/);assert.match(await panel.innerText(),/Passe/);assert(!state.journal.at(-1).answers.some(a=>a.id==='SEF-PN26-M1-021'),'worked example is not an answered QCM');assert.equal(state.journal.at(-1).answers.length,10);
   const roundTrip=await page.evaluate(()=>{const s=JSON.parse(localStorage.getItem('qpjb-sef-parcours-01')),all=JSON.parse(document.querySelector('#training-data').textContent).exercises;return QPJBParcours.importProgress(JSON.stringify(QPJBParcours.exportProgress(s,all,{}))).journal.at(-1)});
   assert.deepEqual(roundTrip,state.journal.at(-1));
   await page.locator('#done-home').click();await page.locator('#parcours-start').waitFor({state:'visible'});
   const eventS3=state.journal.at(-1),readPlan=()=>page.evaluate(()=>{const s=JSON.parse(localStorage.getItem('qpjb-sef-parcours-01')),all=JSON.parse(document.querySelector('#training-data').textContent).exercises;return QPJBParcours.consolidationPlan(s,all,10)});
   let plan=await readPlan(),weakSessions=0;
   // Skipping is not evidence of a misconception. Create actual wrong answers
   // through the UI until the native planner, not a forged state, offers review.
   while(!plan.available&&weakSessions<6){
    await start();
    for(let i=0;i<10;i++){
     await step(i+1,10);await page.locator('#show-choices').click();
     const wrong=await page.evaluate(i=>{
      const s=JSON.parse(localStorage.getItem('qpjb-sef-parcours-01')),all=JSON.parse(document.querySelector('#training-data').textContent).exercises;
      const q=all.find(q=>q.id===s.active.ids[i]);
      const buttons=[...document.querySelectorAll('#answers [data-choice]')];
      const b=buttons.find(b=>b.getAttribute('aria-label').split(' : ').slice(1).join(' : ')!==q.answer);
      if(!b)throw Error('No wrong answer in UI');return b.dataset.choice;
     },i);
     await page.locator('#answers [data-choice="'+wrong+'"]').click();
     await page.locator('#answer-feedback').waitFor({state:'visible'});
     await page.locator('#next').click();
    }
    await page.locator('#done-home').waitFor({state:'visible'});
    state=await snapshot();assert(state.journal.at(-1).answers.every(a=>a.result==='wrong'),'actual wrong answers persisted');
    await page.locator('#done-home').click();await page.locator('#parcours-start').waitFor({state:'visible'});
    weakSessions++;plan=await readPlan();
   }
   assert(plan.available,'actual UI errors must eventually offer consolidation');
   const completedAtConsolidation=state.completed;
   assert.deepEqual(state.journal.find(e=>e.mode==='parcours'&&e.session===3),eventS3);
   const mastery={skills:state.skills,micros:state.micros,axes:state.axes};
   await start('#parcours-consolidation');let active=(await snapshot()).active;
   assert.equal(active.mode,'consolidation');assert.deepEqual(active.ids,plan.items.map(x=>x.id));assert(!active.orderReferenceIds&&!active.orderSkillBase);
   const n=active.ids.length;
   for(let i=0;i<n;i++){
    await step(i+1,n);await skip();
    if(i===0){await step(2,n);const saved=(await snapshot()).active;await reload();await start();await step(2,n);assert.deepEqual((await snapshot()).active,saved,'exact consolidation resume')}
   }
   await page.locator('#done-home').waitFor({state:'visible'});
   state=await snapshot();assert.equal(state.completed,completedAtConsolidation);assert.equal(state.journal.at(-1).mode,'consolidation');
   assert.deepEqual(state.journal.at(-1).answers.map(a=>a.id),plan.items.map(x=>x.id));
   assert.deepEqual({skills:state.skills,micros:state.micros,axes:state.axes},mastery,'consolidation does not establish mastery');
   await page.locator('#done-home').click();await page.locator('#new').waitFor({state:'visible'});
   const guideBefore=await snapshot();await start('#new');await skip();
   assert.deepEqual(await snapshot(),guideBefore,'free quiz does not mutate guided state');
   await write(fixture.legacy);await reload();await start();await step(2,10);
   assert.deepEqual((await snapshot()).active,fixture.legacy.active,'legacy active session is not rewritten');
   assert.deepEqual(errors,[]);
   rows.push({width,session:3,reference:fixture.reference,actual:displayed,old:fixture.old.id,next:fixture.next.id,renderedHand:true,offlineFirstVisit:true,activeResume:true,legacyResume:true,consolidation:{afterSession:completedAtConsolidation,weakSessions,ids:plan.items.map(x=>x.id),resume:true,masteryUnchanged:true},journal:true,exportImport:true,freeQuizIsolation:true,pageErrors:errors});
  }finally{await context.close()}
 }
 console.log(JSON.stringify({status:'PASS',browser:engine,version:browser.version(),refused,rows},null,2));
 }finally{await browser.close()}
}
main().catch(e=>{console.error(e.stack||e);process.exitCode=1}).finally(()=>server.close());
